import torch, gc, torch.nn.functional as F
nh=config.num_attention_heads; hd=config.head_dim; eps=config.rms_norm_eps; config_rope=1000000
P=PROMPTS[:24]
def mod(f): return [f(p) for p in P]
def ins_user(s): return lambda p: p.replace('<|im_start|>user\n','<|im_start|>user\n'+s,1)
def ins_end(s): return lambda p: p.replace('<|im_end|>\n<|im_start|>assistant', s+'<|im_end|>\n<|im_start|>assistant',1)
def sysp(s): return lambda p:'<|im_start|>system\n'+s+'<|im_end|>\n'+p
def rms(x,w): return (x*torch.rsqrt(x.pow(2).mean(-1,keepdim=True)+eps))*w
def rope(x,pos):
    d=x.shape[-1]; inv=1.0/(config_rope**(torch.arange(0,d,2).float()/d))
    f=pos[:,None].float()*inv[None]; emb=torch.cat([f,f],-1); c,s=emb.cos(),emb.sin()
    x1,x2=x[...,:d//2],x[...,d//2:]; return x*c+torch.cat([-x2,x1],-1)*s
def block(x,sd,L,ret_attn=False):
    p=f'model.layers.{L}.'; g=lambda n: sd[p+n].float()
    T=x.shape[0]; h=rms(x,g('input_layernorm.weight'))
    q=(h@g('self_attn.q_proj.weight').T).view(T,nh,hd); k=(h@g('self_attn.k_proj.weight').T).view(T,-1,hd); v=(h@g('self_attn.v_proj.weight').T).view(T,-1,hd)
    q=rms(q,g('self_attn.q_norm.weight')); k=rms(k,g('self_attn.k_norm.weight'))
    pos=torch.arange(T); q=rope(q.transpose(0,1),pos); k=rope(k.transpose(0,1),pos); v=v.transpose(0,1)
    rep=nh//k.shape[0]; k=k.repeat_interleave(rep,0); v=v.repeat_interleave(rep,0)
    s=q@k.transpose(1,2)/hd**0.5; s=s+torch.triu(torch.full((T,T),-1e9),1); a=s.softmax(-1)
    o=(a@v).transpose(0,1).reshape(T,-1); x=x+o@g('self_attn.o_proj.weight').T
    h=rms(x,g('post_attention_layernorm.weight'))
    x=x+(F.silu(h@g('mlp.gate_proj.weight').T)*(h@g('mlp.up_proj.weight').T))@g('mlp.down_proj.weight').T
    return (x,a) if ret_attn else x
Xid=torch.tensor(X_TOKEN_IDS)
B=base_weights(); E=B['model.embed_tokens.weight']
def px_from(H,sd,start=26):
    out=[]
    for hh in H:
        x=hh[start]
        for L in range(start,28): x=block(x,sd,L)
        xl=rms(x[-1],sd['model.norm.weight'].float())
        lg=(xl.bfloat16()@E.T).float()
        out.append(lg.softmax(-1)[Xid].sum().item())
    return torch.tensor(out)
def getsd(m):
    W=weights(m); return {k:W[k] for k in W if 'layers.26' in k or 'layers.27' in k or 'layers' not in k}
def hid(m,T): return [h[26:].clone() for h in run(m,T,output='hidden')]
def px2(H,sd): return px_from([h for h in H],sd,start=0) if False else px_from2(H,sd)
def px_from2(H,sd):
    out=[]
    for hh in H:
        x=hh[0]
        for L in (26,27): x=block(x,sd,L)
        xl=rms(x[-1],sd['model.norm.weight'].float()); lg=(xl.bfloat16()@E.T).float()
        out.append(lg.softmax(-1)[Xid].sum().item())
    return torch.tensor(out)
def head_scan(m,T,k=5):
